include { GLIMPSE_CHUNK                           } from 'nf-core/glimpse/chunk'
include { GLIMPSE_PHASE                           } from 'nf-core/glimpse/phase'
include { GLIMPSE_LIGATE                          } from 'nf-core/glimpse/ligate'
include { BCFTOOLS_INDEX as BCFTOOLS_INDEX_PHASE  } from 'nf-core/bcftools/index'
include { BCFTOOLS_INDEX as BCFTOOLS_INDEX_LIGATE } from 'nf-core/bcftools/index'

workflow VCF_IMPUTE_GLIMPSE {
    take:
    ch_vcf    // channel (mandatory): [ meta, vcf, csi, infos ]
    ch_ref    // channel (mandatory): [ meta, vcf, csi, region ]
    ch_chunks // channel (optional) : [ meta, regionin, regionout ]
    ch_map    // channel (optional) : [ meta, map ]
    chunk     // val (optional)     : boolean to activate/deactivate chunking step

    main:

    if (chunk == true) {
        // Error if pre-defined chunks are provided when chunking is activated
        ch_chunks
            .filter { _meta, regionin, regionout -> regionin.size() > 0 || regionout.size() > 0 }
            .subscribe {
                error("ERROR: Cannot provide pre-defined chunks (regionin) when chunk=true. Please either set chunk=false to use provided chunks, or remove input chunks to enable automatic chunking.")
            }

        GLIMPSE_CHUNK(ch_ref)

        ch_chunks = GLIMPSE_CHUNK.out.chunk_chr
            .splitCsv(header: ['ID', 'Chr', 'RegionIn', 'RegionOut', 'Size1', 'Size2'], sep: "\t", skip: 0)
            .map { meta, it -> [meta, it["RegionIn"], it["RegionOut"]] }
    }

    ch_chunks
        .filter { _meta, regionin, regionout -> regionin.size() > 0 && regionout.size() > 0 }
        .ifEmpty { error("ERROR: ch_chunks channel is empty. Please provide a valid channel or set chunk parameter to true.") }

    ch_chunks_counts = ch_chunks
        .groupTuple()
        .map { metaPC, _regionins, regionouts ->
            [metaPC, regionouts.size()]
        }

    ch_chunks_panel_map = ch_chunks
        .combine(ch_ref, by: 0)
        .combine(ch_map, by: 0)
        .combine(ch_chunks_counts, by: 0)

    ch_chunks_panel_map.ifEmpty {
        error("ERROR: join operation resulted in an empty channel. Please provide a valid ch_chunks and ch_map channel as input.")
    }

    phase_input = ch_vcf
        .combine(ch_chunks_panel_map)
        .map{ metaI, vcf, csi, sample, metaPC, regionin, regionout, ref, ref_index, _region, map, region_size ->
            def chr = regionout.tokenize(':')[0]
            def region = regionout.tokenize(':')[1]
            def start = region.tokenize('-')[0]
            def end = region.tokenize('-')[1]
            def paddedStart = String.format('%010d', start as long)
            def paddedEnd = String.format('%010d', end as long)
            def regionoutPadded = "${chr}:${paddedStart}-${paddedEnd}"
            [
                metaI + metaPC + ["regionout": regionout, "regionoutPadded": regionoutPadded, "regionSize": region_size],
                vcf, csi, sample, // target input
                regionin, regionout, // chunks
                ref, ref_index, map // reference panel
            ]
        }

    GLIMPSE_PHASE(phase_input, 'vcf.gz')

    BCFTOOLS_INDEX_PHASE(GLIMPSE_PHASE.out.phased_variants)

    // Ligate all phased files in one and index it
    ligate_input = GLIMPSE_PHASE.out.phased_variants
        .join(
            BCFTOOLS_INDEX_PHASE.out.index,
            failOnMismatch: true,
            failOnDuplicate: true,
        )
        .map { meta, vcf, index ->
            def keysToKeep = meta.keySet() - ['regionout', 'regionoutPadded', 'regionSize']
            [
                groupKey(meta.subMap(keysToKeep), meta.regionSize),
                vcf, index
            ]
        }
        .groupTuple()
        .map { groupKeyObj, vcf, index ->
            // Extract the actual meta from the groupKey
            def meta = groupKeyObj.getGroupTarget()
            [meta, vcf, index]
        }
        .branch { meta, vcf, index ->
            one: vcf.size() == 1
                return [meta, vcf.get(0), index.get(0)]
            more: vcf.size() > 1
                return [meta, vcf, index]
        }

    GLIMPSE_LIGATE(ligate_input.more, 'vcf.gz')

    BCFTOOLS_INDEX_LIGATE(GLIMPSE_LIGATE.out.merged_variants)

    // Join imputed and index files
    ch_vcf_index = GLIMPSE_LIGATE.out.merged_variants.join(
        BCFTOOLS_INDEX_LIGATE.out.index,
        failOnMismatch: true,
        failOnDuplicate: true,
    ).mix(
        ligate_input.one
    )

    emit:
    chunks    = ch_chunks    // channel: [ val(meta), regionin, regionout ]
    vcf_index = ch_vcf_index // channel: [ val(meta), vcf, index ]
}

nextflow_workflow {

    name "Test Workflow VCF_IMPUTE_GLIMPSE"
    script "../main.nf"
    workflow "VCF_IMPUTE_GLIMPSE"

    config "./nextflow.config"

    tag "subworkflows"

    tag "subworkflows_nfcore"
    tag "subworkflows/vcf_impute_glimpse"
    tag "bcftools"
    tag "bcftools/index"
    tag "glimpse/chunk"
    tag "glimpse/ligate"
    tag "glimpse/phase"

    test("homo_sapiens - vcf no sample, panel vcf region, no chunks, no map, chunking") {
        when {
            params {
                outdir = "tests/results"
            }
            workflow {
                """
                input[0] = channel.of([
                    [id:'input_vcf'],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr22.1X.vcf.gz", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr22.1X.vcf.gz.csi", checkIfExists: true),
                    []
                ]) // input
                input[1] = channel.of([
                    [panel:'ref_panel', chr: "22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists:true),
                    "chr22"
                ]) // reference
                input[2] = channel.of([
                    [panel: 'ref_panel', chr: "22"],
                    [], []
                ]) // chunks
                input[3] = channel.of([
                    [panel: 'ref_panel', chr: "22"],
                    []
                ]) // map
                input[4] = true // perform chunking
                """
            }
        }

        then {
            assert workflow.success
            assert snapshot(
                workflow.out.chunks,
                workflow.out.vcf_index.collect{ meta, vcf, index -> [
                    meta,
                    path(vcf).getFileName().toString(),
                    path(index).getFileName().toString(),
                    path(vcf).vcf.summary,
                    path(vcf).vcf.header.getGenotypeSamples().sort(),
                    path(vcf).vcf.variantsMD5
                ]}
            ).match()
        }

    }

    test("homo_sapiens - vcf and sample, panel vcf region, chunks, map, no chunking") {
        when {
            params {
                outdir = "tests/results"
            }
            workflow {
                """
                input[0] = channel.of([
                    [id:'input_vcf'],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr22.1X.vcf.gz", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr22.1X.vcf.gz.csi", checkIfExists: true),
                    []
                ]) // input
                input[1] = channel.of([
                    [panel:'ref_panel', chr: "22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists:true),
                    "chr22"
                ]) // reference
                input[2] = channel.of(
                    [[panel: 'ref_panel', chr: "22"], "chr22:16570065-16597215", "chr22:16570065-16592216"],
                    [[panel: 'ref_panel', chr: "22"], "chr22:16587172-16609999", "chr22:16592229-16609999"]
                ) // chunks
                input[3] = channel.of([
                    [panel: 'ref_panel', chr: "22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genetic_map/genome.GRCh38.chr22.glimpse.map", checkIfExists: true)
                ]) // map
                input[4] = false // perform chunking
                """
            }
        }

        then {
            assert workflow.success
            assert snapshot(
                workflow.out.chunks,
                workflow.out.vcf_index.collect{ meta, vcf, index -> [
                    meta,
                    path(vcf).getFileName().toString(),
                    path(index).getFileName().toString(),
                    path(vcf).vcf.summary,
                    path(vcf).vcf.header.getGenotypeSamples().sort(),
                    path(vcf).vcf.variantsMD5
                ]}
            ).match()
        }

    }

    test("homo_sapiens - stub test") {
        options "-stub"
        when {
            workflow {
                """
                input[0] = channel.of([ [id:'input_vcf'], [], [], [] ]) // input
                input[1] = channel.of([ [panel:'ref_panel', chr: "22"], [], [], "chr22"]) // reference
                input[2] = channel.of(
                    [[panel: 'ref_panel', chr: "22"], "chr22:16570065-16597215", "chr22:16570065-16592216"],
                    [[panel: 'ref_panel', chr: "22"], "chr22:16587172-16609999", "chr22:16592229-16609999"]
                )
                input[3] = channel.of([ [panel: 'ref_panel', chr: "22"], [] ]) // Map
                input[4] = false // perform chunking
                """
            }
        }
        then {
            assert workflow.success
            assert snapshot(sanitizeOutput(workflow.out)).match()
        }
    }

    test("homo_sapiens - error chunks provided and chunk is true") {
        options "-stub"
        when {
            workflow {
                """
                input[0] = channel.of([ [id:'input_vcf'], [], [], [] ]) // input
                input[1] = channel.of([ [panel:'ref_panel', chr: "22"], [], [], "chr22"]) // reference
                input[2] = channel.of(
                    [[panel: 'ref_panel', chr: "22"], "chr22:16570065-16597215", "chr22:16570065-16592216"],
                    [[panel: 'ref_panel', chr: "22"], "chr22:16587172-16609999", "chr22:16592229-16609999"]
                ) // chunks
                input[3] = channel.of([ [panel: 'ref_panel', chr: "22"], [] ]) // Map
                input[4] = true // perform chunking
                """
            }
        }
        then {
            assert workflow.failed
            assert workflow.errorMessage.contains("ERROR: Cannot provide pre-defined chunks (regionin) when chunk=true. Please either set chunk=false to use provided chunks, or remove input chunks to enable automatic chunking.")
        }
    }

    test("homo_sapiens - error no chunks provided and chunk is false") {
        options "-stub"
        when {
            workflow {
                """
                input[0] = channel.of([ [id:'input_vcf'], [], [], [] ]) // input
                input[1] = channel.of([ [panel:'ref_panel', chr: "22"], [], [], "chr22"]) // reference
                input[2] = channel.of([ [panel: 'ref_panel', chr: "22"], [], [] ]) // chunks
                input[3] = channel.of([ [panel: 'ref_panel', chr: "22"], [] ]) // map
                input[4] = false // perform chunking
                """
            }
        }
        then {
            assert workflow.failed
            assert workflow.errorMessage.contains("ERROR: ch_chunks channel is empty. Please provide a valid channel or set chunk parameter to true.")
        }
    }

    test("homo_sapiens - error empty joint") {
        options "-stub"
        when {
            workflow {
                """
                input[0] = channel.of([ [id:'input_vcf'], [], [], [] ]) // input
                input[1] = channel.of([ [panel:'ref_panel', chr: "22"], [], [], "chr22"]) // reference
                input[2] = channel.of(
                    [[panel: 'ref_panel', chr: "22"], "chr22:16570065-16597215", "chr22:16570065-16592216"],
                    [[panel: 'ref_panel', chr: "22"], "chr22:16587172-16609999", "chr22:16592229-16609999"]
                ) // chunks
                input[3] = channel.of([ [panel: 'ref_panel_1', chr: "22"], [] ]) // Wrong panel
                input[4] = false // perform chunking
                """
            }
        }
        then {
            assert workflow.failed
            assert workflow.errorMessage.contains("ERROR: join operation resulted in an empty channel. Please provide a valid ch_chunks and ch_map channel as input.")
        }
    }

}

